def find_pack(dims, N=16, rot=False, holes=3, node_limit=3_000_000):
    full=(1<<N)-1; n=len(dims); nodes=0
    opts=[]
    for h,w in dims:
        oo=[(h,w)]
        if rot and h!=w:oo.append((w,h))
        opts.append(oo)
    @lru_cache(None)
    def rec(rows, remain, left):
        nonlocal nodes
        nodes+=1
        if nodes>node_limit: return None
        if remain==0:
            return () if left>=0 else None
        # lower area bound
        # first free coordinate
        found=False
        for r in range(N):
            m=(~rows[r])&full
            if m:
                c=(m&-m).bit_length()-1;found=True;break
        if not found:return None
        # try placing rectangles before hole to avoid waste
        for i in range(n):
            if not ((remain>>i)&1):continue
            for h,w in opts[i]:
                if r+h>N or c+w>N:continue
                mask=((1<<w)-1)<<c
                if all(not (rows[rr]&mask) for rr in range(r,r+h)):
                    rr=list(rows)
                    for y in range(r,r+h):rr[y]|=mask
                    ans=rec(tuple(rr),remain^(1<<i),left)
                    if ans is not None:return ((i,r,c,h,w),)+ans
        if left:
            rr=list(rows);rr[r]|=1<<c
            ans=rec(tuple(rr),remain,left-1)
            if ans is not None:return ((-1,r,c,1,1),)+ans
        return None
    path=rec(tuple([0]*N),(1<<n)-1,holes)
    return path,nodes,rec.cache_info()
